const supportedBrowserLanguages = new Set(['en', 'fr', 'de', 'pt', 'it', 'nl', 'sv', 'da', 'no', 'fi', 'pl', 'uk', 'ru', 'ja', 'ko', 'zh', 'ar', 'tr', 'cs', 'ro', 'hu']);
const browserLanguage = (navigator.languages?.[0] || navigator.language || '').toLowerCase().split('-')[0];
const detectedLanguage = supportedBrowserLanguages.has(browserLanguage) ? 'en' : 'gl';

const setLanguage = (language, remember = true) => {
  const copy = translations[language] || translations.gl;
  document.documentElement.lang = language;
  document.title = copy.title;
  document.querySelector('meta[name="description"]')?.setAttribute('content', copy.meta_description);
  document.querySelectorAll('[data-i18n]').forEach((element) => {
    const value = copy[element.dataset.i18n];
    if (!value) return;
    if (element.hasAttribute('data-i18n-html')) element.innerHTML = value;
    else element.textContent = value;
  });
  document.querySelectorAll('[data-i18n-aria-label]').forEach((element) => {
    const value = copy[element.dataset.i18nAriaLabel];
    if (value) element.setAttribute('aria-label', value);
  });
  document.querySelectorAll('[data-i18n-alt]').forEach((element) => {
    const value = copy[element.dataset.i18nAlt];
    if (value) element.setAttribute('alt', value);
  });
  document.querySelectorAll('[data-language]').forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.language === language)));
  if (remember) localStorage.setItem('maxibasket-language', language);
};

const storedLanguage = localStorage.getItem('maxibasket-language');
setLanguage(storedLanguage === 'en' || storedLanguage === 'gl' ? storedLanguage : detectedLanguage, false);
document.querySelectorAll('[data-language]').forEach((button) => button.addEventListener('click', () => setLanguage(button.dataset.language)));

const toggle = document.querySelector('.nav-toggle');
const nav = document.querySelector('nav');
toggle?.addEventListener('click', () => {
  const open = nav.classList.toggle('open');
  toggle.setAttribute('aria-expanded', String(open));
});
document.querySelectorAll('nav a').forEach((link) => link.addEventListener('click', () => {
  nav.classList.remove('open');
  toggle?.setAttribute('aria-expanded', 'false');
}));
